import React from "react";
import { useCurrentFrame, useVideoConfig, AbsoluteFill, spring, random } from '../remotionShim';
const fontFamily = '"Helvetica Neue", Helvetica, Arial, sans-serif';

// Zod Schema representing all customizable properties


export type RolodexDeckProps = Record<string, any>;

// Corner decoration component matching the reference image's index card marks
const CornerMarks: React.FC<{ color: string; width: number; height: number }> = ({ color, width, height }) => {
  const size = Math.min(width, height) * 0.04;
  const stroke = Math.max(1, Math.min(width, height) * 0.002);
  const offset = Math.min(width, height) * 0.03;

  return (
    <div style={{ position: "absolute", top: 0, left: 0, right: 0, bottom: 0, pointerEvents: "none", transition: "none" }}>
      {/* Top Left */}
      <div style={{ position: "absolute", top: offset, left: offset, width: size, height: size, borderTop: `${stroke}px solid ${color}`, borderLeft: `${stroke}px solid ${color}`, transition: "none" }} />
      {/* Top Right */}
      <div style={{ position: "absolute", top: offset, right: offset, width: size, height: size, borderTop: `${stroke}px solid ${color}`, borderRight: `${stroke}px solid ${color}`, transition: "none" }} />
      {/* Bottom Left */}
      <div style={{ position: "absolute", bottom: offset, left: offset, width: size, height: size, borderBottom: `${stroke}px solid ${color}`, borderLeft: `${stroke}px solid ${color}`, transition: "none" }} />
      {/* Bottom Right */}
      <div style={{ position: "absolute", bottom: offset, right: offset, width: size, height: size, borderBottom: `${stroke}px solid ${color}`, borderRight: `${stroke}px solid ${color}`, transition: "none" }} />
    </div>
  );
};

// Flickering Speed Lines to simulate fast-rolling motion blur
const SpeedLines: React.FC<{
  speedIntensity: number;
  width: number;
  height: number;
  color: string;
}> = ({ speedIntensity, width, height, color }) => {
  const frame = useCurrentFrame();
  if (speedIntensity <= 0.05) return null;

  const numLines = 16;
  return (
    <AbsoluteFill style={{ pointerEvents: "none", transition: "none" }}>
      {Array.from({ length: numLines }).map((_, i) => {
        const isLeft = i < numLines / 2;
        
        // Generate deterministic pseudo-random values per frame for organic flicker
        const randomWidth = random(`speed-line-w-${i}-${frame}`) * width * 0.28 * speedIntensity;
        const randomY = (0.2 + random(`speed-line-y-${i}-${frame}`) * 0.6) * height;
        const randomOpacity = random(`speed-line-o-${i}-${frame}`) * 0.55 * speedIntensity;
        const xOffset = width * 0.02 + random(`speed-line-x-${i}-${frame}`) * width * 0.05;

        const style: React.CSSProperties = {
          position: "absolute",
          top: randomY,
          [isLeft ? "left" : "right"]: xOffset,
          width: randomWidth,
          height: Math.max(1, Math.min(width, height) * 0.003),
          backgroundColor: color,
          opacity: randomOpacity,
          borderRadius: 4,
          transition: "none",
        };

        return <div key={i} style={style} />;
      })}
    </AbsoluteFill>
  );
};

export const RolodexDeck: React.FC<RolodexDeckProps> = ({
  backgroundColor = "#030303",
  transparentBackground = false,
  durationInSeconds = 10,
  items = [
    "Equity Financing",
    "Debt Financing",
    "Hybrid Financing",
    "Alternative and Non-Traditional Methods",
    "Venture Capital (VC)",
    "Private Equity (PE)",
    "Angel Investing",
    "Strategic Partnerships",
    "Corporate Bonds",
    "Debentures",
    "Bank Loans",
    "Lines of Credit",
    "Private Credit",
  ],
  cardColor = "#ffffff",
  textColor = "#000000",
  speedLinesColor = "#ffffff",
  showSpeedLines = true,
  tiltAngle = -12,
}) => {
  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();

  const totalFrames = fps * durationInSeconds;
  
  // Dedicate 78% of the video to accelerating roll, and the rest to spring settle hold
  const rollFrames = Math.floor(totalFrames * 0.78);

  // Snapped Index interpolation for physical mechanical clicks
  const getSnappedIndex = (rawIndex: number) => {
    const floor = Math.floor(rawIndex);
    const decimal = rawIndex - floor;
    // Fast flip logic: card stays still during first half, then snaps over in the second half
    const smoothedDecimal = decimal < 0.45 ? 0 : (decimal - 0.45) / 0.55;
    // Ease the snap using a clean sine wave
    const easedDecimal = Math.sin((smoothedDecimal * Math.PI) / 2);
    return floor + easedDecimal;
  };

  // Determine underlying continuous index
  let snappedIndex: number;
  let speedIntensity = 0;
  let bounceRotation = 0;
  let bounceY = 0;

  if (frame < rollFrames) {
    const norm = frame / rollFrames;
    // Exponential acceleration
    const eased = Math.pow(norm, 2.5);
    const rawIndex = eased * (items.length - 1);
    snappedIndex = getSnappedIndex(rawIndex);
    
    // Speed peaks right before the final settle
    speedIntensity = Math.pow(norm, 2.0);
  } else {
    // Settle perfectly on the final index with a physical spring reaction
    snappedIndex = items.length - 1;
    
    // Simulate mechanical bounce shockwave absorption
    const springVal = spring({
      frame: frame - rollFrames,
      fps,
      config: {
        damping: 14,
        mass: 0.6,
        stiffness: 110,
      },
    });

    const bounceScale = 1 - springVal; // Dampens down to 0 over time
    bounceRotation = Math.sin((frame - rollFrames) * 0.35) * 8 * bounceScale;
    bounceY = Math.sin((frame - rollFrames) * 0.35) * 16 * bounceScale;
  }

  // Safe background color check
  const bgColor = transparentBackground ? "transparent" : backgroundColor;

  // Render only visible cards to maintain performance
  const visibleCards = items
    .map((item, index) => ({ item, index }))
    .filter(({ index }) => {
      const diff = index - snappedIndex;
      return diff >= -1.2 && diff <= 12;
    });

  return (
    <AbsoluteFill
      style={{
        backgroundColor: bgColor,
        display: "flex",
        justifyContent: "center",
        alignItems: "center",
        overflow: "hidden",
        transition: "none",
      }}
    >
      {/* Conditional speed lines representing dynamic wind/motion blur */}
      {showSpeedLines && (
        <SpeedLines
          speedIntensity={speedIntensity}
          width={width}
          height={height}
          color={speedLinesColor}
        />
      )}

      {/* 3D Perspective Wrapper */}
      <div
        style={{
          perspective: "1200px",
          perspectiveOrigin: "50% 35%",
          transformStyle: "preserve-3d",
          width: "100%",
          height: "100%",
          position: "relative",
          display: "flex",
          justifyContent: "center",
          alignItems: "center",
          transition: "none",
        }}
      >
        {visibleCards.map(({ item, index }) => {
          const diff = index - snappedIndex;
          
          let transformStr = "";
          let opacity = 1;
          let currentBounceY = 0;
          let currentBounceRot = 0;

          // Apply physical bounce ONLY to the active landing card
          if (index === items.length - 1) {
            currentBounceY = bounceY;
            currentBounceRot = bounceRotation;
          }

          if (diff === 0) {
            // Front-most active card
            transformStr = `translateY(${currentBounceY}px) translateZ(0px) rotateX(${tiltAngle + currentBounceRot}deg)`;
            opacity = 1;
          } else if (diff > 0) {
            // Receding background cards stack
            const zOffset = diff * -48;
            const yOffset = diff * -24 + currentBounceY * 0.2;
            const xRotation = tiltAngle - diff * 2.2 + currentBounceRot * 0.2;
            const scale = Math.max(0.5, 1 - diff * 0.022);

            transformStr = `translateY(${yOffset}px) translateZ(${zOffset}px) rotateX(${xRotation}deg) scale(${scale})`;
            opacity = Math.max(0, 1 - diff * 0.08);
          } else {
            // Outgoing flipped cards (fall forward and rotate out)
            const progress = Math.abs(diff);
            const xRotation = tiltAngle + progress * 95;
            const yOffset = progress * 220 + currentBounceY;
            const zOffset = progress * 110;

            transformStr = `translateY(${yOffset}px) translateZ(${zOffset}px) rotateX(${xRotation}deg)`;
            opacity = Math.max(0, 1 - progress * 1.8);
          }

          // Generate perfect index layers (Z-Index ordering)
          let zIndex = 1000 - Math.round(diff * 15);
          if (diff < 0) {
            zIndex = 1000 + Math.round(Math.abs(diff) * 20);
          }

          // Shading overlay to naturally darken back cards
          const darkOverlay = Math.min(0.85, Math.max(0, diff * 0.08));

          // Responsive Card Sizing matching reference occupancy
          const cardWidth = width * 0.65;
          const cardHeight = height * 0.28;

          // Adaptive font size logic with generous padding for elegant text presentation
          const getFontSize = (text: string) => {
            const baseSize = height * 0.072;
            if (text.length > 28) return baseSize * 0.52;
            if (text.length > 18) return baseSize * 0.72;
            return baseSize;
          };

          return (
            <div
              key={index}
              style={{
                position: "absolute",
                width: cardWidth,
                height: cardHeight,
                top: height * 0.56 - cardHeight / 2,
                left: width * 0.5 - cardWidth / 2,
                backgroundColor: cardColor,
                borderRadius: Math.min(width, height) * 0.008,
                border: "1px solid rgba(0,0,0,0.15)",
                boxShadow: "0 15px 35px rgba(0,0,0,0.4), 0 5px 12px rgba(0,0,0,0.2)",
                display: "flex",
                justifyContent: "center",
                alignItems: "center",
                padding: "24px 48px",
                boxSizing: "border-box",
                transform: transformStr,
                opacity,
                zIndex,
                transformOrigin: "bottom center",
                backfaceVisibility: "hidden",
                transition: "none",
              }}
            >
              {/* Internal atmospheric shadow layer */}
              <div
                style={{
                  position: "absolute",
                  top: 0,
                  left: 0,
                  right: 0,
                  bottom: 0,
                  backgroundColor: "#000000",
                  opacity: darkOverlay,
                  borderRadius: Math.min(width, height) * 0.008,
                  pointerEvents: "none",
                  transition: "none",
                }}
              />

              {/* Refined elegant inner card inlay outline */}
              <div
                style={{
                  position: "absolute",
                  top: "12px",
                  left: "12px",
                  right: "12px",
                  bottom: "12px",
                  border: `1px solid ${textColor}18`,
                  borderRadius: Math.min(width, height) * 0.005,
                  pointerEvents: "none",
                  transition: "none",
                }}
              />

              {/* L-shaped corner indicators on the front active card */}
              {diff <= 0.05 && diff >= -0.05 && (
                <CornerMarks
                  color="rgba(0, 0, 0, 0.45)"
                  width={cardWidth}
                  height={cardHeight}
                />
              )}

              {/* Premium Bold Helvetica Text, Italicized, All-caps with Drop Shadow */}
              <div
                style={{
                  fontFamily,
                  fontWeight: "bold",
                  fontStyle: "italic",
                  fontSize: getFontSize(item),
                  color: textColor,
                  textAlign: "center",
                  letterSpacing: "0.02em",
                  lineHeight: 1.15,
                  textTransform: "uppercase",
                  userSelect: "none",
                  transition: "none",
                  textShadow: "2px 2px 5px rgba(0, 0, 0, 0.25)",
                }}
              >
                {item}
              </div>
            </div>
          );
        })}
      </div>
    </AbsoluteFill>
  );
};

export default RolodexDeck;